524	\begin{definition}[Dehomogenization]
525	  \label{def:P1_dehomogenize}
526	  \lean{AlgebraicGeometry.P1.dehomogenize}
527	  \leanok
528	  For \(i \in \{0,1\}\), the dehomogenization at \(X_i\) is the \(k\)-algebra homomorphism
529	  \(\delta_i : k[X_0, X_1] \to k[t]\) with \(\delta_i(X_i) = 1\) and \(\delta_i(X_j) = t\) for
530	  \(j \neq i\).
531	\end{definition}
