533	\begin{definition}[From polynomials to the chart ring]
534	  \label{def:P1_polyToAway}
535	  \lean{AlgebraicGeometry.P1.polyToAway}
536	  \uses{def:P1_chartCoord}
537	  \leanok
538	  For \(i, j \in \{0,1\}\), the \(k\)-algebra homomorphism \(k[t] \to A_{(X_i)}\) given by
539	  evaluation at the chart coordinate, \(t \mapsto t_{ij}\).
540	\end{definition}
541	
542	\begin{definition}[From the chart ring to polynomials]
543	  \label{def:P1_awayToPoly}
544	  \lean{AlgebraicGeometry.P1.awayToPoly}
545	  \uses{def:P1_dehomogenize}
546	  \leanok
547	  For \(i \in \{0,1\}\), the \(k\)-algebra homomorphism \(A_{(X_i)} \to k[t]\) sending a
548	  degree-zero fraction \(a / X_i^n\) (with \(a\) homogeneous of degree \(n\)) to
549	  \(\delta_i(a)\).
550	\end{definition}
551	\begin{proof}
552	  \leanok
553	  Well-definedness: \(\delta_i(X_i) = 1\) is a unit of \(k[t]\), so \(\delta_i\) extends to
554	  the localization \(A_{X_i} \to k[t]\) by the universal property of localization; on the
555	  degree-zero subring its value on \(a / X_i^n\) is
556	  \(\delta_i(a)\,\delta_i(X_i)^{-n} = \delta_i(a)\).
557	\end{proof}
