559	\begin{lemma}[One composite is the identity]
560	  \label{lem:P1_awayToPoly_polyToAway}
561	  \lean{AlgebraicGeometry.P1.awayToPoly_comp_polyToAway}
562	  \uses{def:P1_polyToAway, def:P1_awayToPoly}
563	  \leanok
564	  For \(i \neq j\), the composite \(k[t] \to A_{(X_i)} \to k[t]\) of
565	  \ref{def:P1_polyToAway} followed by \ref{def:P1_awayToPoly} is the identity.
566	\end{lemma}
567	\begin{proof}
568	  \leanok
569	  Both sides are \(k\)-algebra homomorphisms on \(k[t]\), so it suffices to check the
570	  generator: \(t \mapsto t_{ij} = X_j / X_i \mapsto \delta_i(X_j) = t\).
571	\end{proof}
572	
573	\begin{lemma}[Monomial fractions are powers of the coordinate]
574	  \label{lem:P1_away_monomial}
575	  \lean{AlgebraicGeometry.P1.away_mk_prod_eq}
576	  \uses{def:P1_chartCoord}
577	  \leanok
578	  Let \(i \neq j\) and let \(e_0, e_1 \ge 0\) with \(e_0 + e_1 = a\). Then in \(A_{(X_i)}\)
579	  \[
580	    \frac{X_0^{e_0} X_1^{e_1}}{X_i^{a}} \;=\; t_{ij}^{\,e_j}.
581	  \]
582	\end{lemma}
583	\begin{proof}
584	  \leanok
585	  Since \(X_0^{e_0} X_1^{e_1} = X_i^{e_i} X_j^{e_j}\) and \(a = e_i + e_j\), the left-hand
586	  side is \(X_i^{e_i} X_j^{e_j} / X_i^{e_i + e_j} = X_j^{e_j} / X_i^{e_j}\), which is
587	  \(t_{ij}^{\,e_j}\).
588	\end{proof}
589	
590	\begin{lemma}[Surjectivity onto the chart ring]
591	  \label{lem:P1_polyToAway_surjective}
592	  \lean{AlgebraicGeometry.P1.polyToAway_surjective}
593	  \uses{def:P1_polyToAway}
594	  \leanok
595	  For \(i \neq j\), the homomorphism \(k[t] \to A_{(X_i)}\) of \ref{def:P1_polyToAway} is
596	  surjective.
597	\end{lemma}
598	\begin{proof}
599	  \leanok
600	  \uses{lem:P1_away_monomial, def:P1_gradeZero}
601	  Since \(A\) is generated over \(A_0\) by the degree-one elements \(X_0, X_1\), the
602	  degree-zero localization \(A_{(X_i)}\) is spanned, as a module over \(A_0 = k\)
603	  (\ref{def:P1_gradeZero}), by the fractions \(m / X_i^a\) where \(m\) ranges over the
604	  monomials \(X_0^{e_0} X_1^{e_1}\) of degree \(a\). By \ref{lem:P1_away_monomial} each such
605	  fraction equals \(t_{ij}^{\,e_j}\), which is the image of \(t^{e_j}\). The image of a ring
606	  homomorphism is closed under addition and under multiplication by scalars from \(k\), so it
607	  is all of \(A_{(X_i)}\).
608	\end{proof}
609	
610	\begin{lemma}[The other composite is the identity]
611	  \label{lem:P1_polyToAway_awayToPoly}
612	  \lean{AlgebraicGeometry.P1.polyToAway_comp_awayToPoly}
613	  \uses{def:P1_polyToAway, def:P1_awayToPoly}
614	  \leanok
615	  For \(i \neq j\), the composite \(A_{(X_i)} \to k[t] \to A_{(X_i)}\) of
616	  \ref{def:P1_awayToPoly} followed by \ref{def:P1_polyToAway} is the identity.
617	\end{lemma}
618	\begin{proof}
619	  \leanok
620	  \uses{lem:P1_polyToAway_surjective, lem:P1_awayToPoly_polyToAway}
621	  By \ref{lem:P1_polyToAway_surjective} every element of \(A_{(X_i)}\) is of the form
622	  \(p(t_{ij})\) with \(p \in k[t]\), and on such elements the claim follows from
623	  \ref{lem:P1_awayToPoly_polyToAway}.
624	\end{proof}
625	
626	\begin{definition}[The chart identification]
627	  \label{def:P1_awayAlgEquiv}
628	  \lean{AlgebraicGeometry.P1.awayAlgEquiv}
629	  \uses{def:P1_polyToAway, def:P1_awayToPoly}
630	  \leanok
631	  For \(i \neq j\), the isomorphism of \(k\)-algebras
632	  \(\alpha_i : A_{(X_i)} \cong k[t]\) given by the mutually inverse homomorphisms of
633	  \ref{def:P1_awayToPoly} and \ref{def:P1_polyToAway}; the chart coordinate \(t_{ij}\)
634	  corresponds to \(t\).
635	\end{definition}
