637	  \leanok
638	  \uses{lem:P1_awayToPoly_polyToAway, lem:P1_polyToAway_awayToPoly}
639	  The two composites are the identity by \ref{lem:P1_awayToPoly_polyToAway} and
640	  \ref{lem:P1_polyToAway_awayToPoly}.
641	\end{proof}
