643	\section{The chart overlap and Laurent polynomials}
644	
645	Write \(k[T, T^{-1}]\) for the ring of Laurent polynomials over \(k\).
646	
647	\begin{lemma}[Laurent span]
648	  \label{lem:laurent_span}
649	  \lean{LaurentPolynomial.exists_toLaurent_add_aeval}
650	  \leanok
651	  Every Laurent polynomial \(f \in R[T, T^{-1}]\) over a commutative (semi)ring \(R\) can be
652	  written as \(f = p(T) + q(T^{-1})\) with \(p, q \in R[t]\) ordinary polynomials.
653	\end{lemma}
654	\begin{proof}
655	  \leanok
656	  Split \(f\) into its monomials and collect those with nonnegative exponent into \(p\) and
657	  those with negative exponent into \(q\).
658	\end{proof}
659	
660	\begin{definition}[Restriction from the left chart]
661	  \label{def:P1_awayToOverlapLeft}
662	  \lean{AlgebraicGeometry.P1.awayToOverlapLeft}
663	  \uses{def:P1}
664	  \leanok
665	  The canonical ring homomorphism \(\lambda : A_{(X_0)} \to A_{(X_0 X_1)}\), sending
666	  \(a / X_0^{\,n}\) to \(a X_1^{\,n} / (X_0 X_1)^{n}\).
667	\end{definition}
668	
669	\begin{definition}[Restriction from the right chart]
670	  \label{def:P1_awayToOverlapRight}
671	  \lean{AlgebraicGeometry.P1.awayToOverlapRight}
672	  \uses{def:P1}
673	  \leanok
674	  The canonical ring homomorphism \(\rho : A_{(X_1)} \to A_{(X_0 X_1)}\), sending
675	  \(a / X_1^{\,n}\) to \(a X_0^{\,n} / (X_0 X_1)^{n}\).
676	\end{definition}
677	
678	\begin{lemma}[The two coordinates are mutually inverse on the overlap]
679	  \label{lem:P1_coord_mul}
680	  \lean{AlgebraicGeometry.P1.awayToOverlap_mul_eq_one}
681	  \uses{def:P1_awayToOverlapLeft, def:P1_awayToOverlapRight, def:P1_chartCoord}
682	  \leanok
683	  In \(A_{(X_0 X_1)}\) one has \(\lambda(t_{01}) \cdot \rho(t_{10}) = 1\).
684	\end{lemma}
685	\begin{proof}
686	  \leanok
687	  Computing with the formulas of \ref{def:P1_awayToOverlapLeft} and
688	  \ref{def:P1_awayToOverlapRight}:
689	  \(\lambda(t_{01}) = X_1^2 / (X_0 X_1)\) and \(\rho(t_{10}) = X_0^2 / (X_0 X_1)\), so
690	  \[
691	    \lambda(t_{01}) \cdot \rho(t_{10})
692	      = \frac{X_0^2 X_1^2}{(X_0 X_1)^2} = 1 .
693	  \]
694	\end{proof}
695	
696	\begin{lemma}[The overlap ring is a localization of the chart ring]
697	  \label{lem:P1_overlap_isLocalization}
698	  \lean{AlgebraicGeometry.P1.instAwayAwayNatMvPolynomialFinOfNatSubmoduleHomogeneousSubmoduleXChartCoordHMul}
699	  \uses{def:P1_awayToOverlapLeft, def:P1_chartCoord}
700	  \leanok
701	  The homomorphism \(\lambda\) of \ref{def:P1_awayToOverlapLeft} identifies
702	  \(A_{(X_0 X_1)}\) with the localization of \(A_{(X_0)}\) at the powers of the chart
703	  coordinate \(t_{01}\).
704	\end{lemma}
705	\begin{proof}
706	  \leanok
707	  This is a general property of degree-zero localizations: for homogeneous elements \(f, g\)
708	  of degree one, \(A_{(fg)}\) is the localization of \(A_{(f)}\) away from the degree-zero
709	  fraction \(g/f\). Here \(f = X_0\), \(g = X_1\) and \(g/f = t_{01}\).
710	\end{proof}
711	
712	\begin{definition}[The overlap identification]
713	  \label{def:P1_overlapAlgEquiv}
714	  \lean{AlgebraicGeometry.P1.overlapAlgEquiv}
715	  \uses{def:P1}
716	  \leanok
717	  The isomorphism of \(k\)-algebras \(\theta : A_{(X_0 X_1)} \cong k[T, T^{-1}]\), with
718	  \(T\) the image of the coordinate \(t_{01}\).
719	\end{definition}
720	\begin{proof}
721	  \leanok
722	  \uses{lem:P1_overlap_isLocalization, def:P1_awayAlgEquiv}
723	  By \ref{lem:P1_overlap_isLocalization}, \(A_{(X_0X_1)}\) is the localization of
724	  \(A_{(X_0)}\) at the powers of \(t_{01}\). The isomorphism
725	  \(\alpha_0 : A_{(X_0)} \cong k[t]\) of \ref{def:P1_awayAlgEquiv} carries \(t_{01}\) to
726	  \(t\), hence induces an isomorphism of the two localizations
727	  \(A_{(X_0X_1)} \cong k[t]_{t} = k[T, T^{-1}]\) (localizations at corresponding
728	  multiplicative sets are canonically isomorphic). The map is \(k\)-linear because
729	  \(\alpha_0\) is.
730	\end{proof}
731	
732	\begin{lemma}[Left restriction is \(t \mapsto T\)]
733	  \label{lem:P1_overlap_res_left}
734	  \lean{AlgebraicGeometry.P1.overlapAlgEquiv_awayToOverlapLeft}
735	  \uses{def:P1_overlapAlgEquiv, def:P1_awayAlgEquiv, def:P1_awayToOverlapLeft}
736	  \leanok
737	  For every \(z \in A_{(X_0)}\) one has \(\theta(\lambda(z)) = p(T)\), where
738	  \(p = \alpha_0(z) \in k[t]\). In other words, under the identifications
739	  \(\alpha_0\) and \(\theta\), the restriction \(\lambda\) is the canonical inclusion
740	  \(k[t] \to k[T, T^{-1}]\), \(t \mapsto T\).
741	\end{lemma}
742	\begin{proof}
743	  \leanok
744	  \uses{lem:P1_overlap_isLocalization}
745	  By construction (\ref{def:P1_overlapAlgEquiv}), \(\theta\) is the comparison of
746	  localizations induced by \(\alpha_0\); under such a comparison the localization map
747	  \(\lambda\) of \ref{lem:P1_overlap_isLocalization} corresponds to the localization map
748	  \(k[t] \to k[T, T^{-1}]\).
749	\end{proof}
750	
751	\begin{lemma}[Right restriction is \(t \mapsto T^{-1}\)]
752	  \label{lem:P1_overlap_res_right}
753	  \lean{AlgebraicGeometry.P1.overlapAlgEquiv_awayToOverlapRight}
754	  \uses{def:P1_overlapAlgEquiv, def:P1_awayAlgEquiv, def:P1_awayToOverlapRight}
755	  \leanok
756	  For every \(z \in A_{(X_1)}\) one has \(\theta(\rho(z)) = q(T^{-1})\), where
757	  \(q = \alpha_1(z) \in k[t]\). In other words, under the identifications \(\alpha_1\) and
758	  \(\theta\), the restriction \(\rho\) is the homomorphism \(k[t] \to k[T, T^{-1}]\),
759	  \(t \mapsto T^{-1}\).
760	\end{lemma}
761	\begin{proof}
762	  \leanok
763	  \uses{lem:P1_coord_mul, lem:P1_overlap_res_left, lem:P1_polyToAway_surjective}
764	  By \ref{lem:P1_overlap_res_left} the image of \(\lambda(t_{01})\) under \(\theta\) is
765	  \(T\), and by \ref{lem:P1_coord_mul} \(\lambda(t_{01})\,\rho(t_{10}) = 1\); applying
766	  \(\theta\) gives \(\theta(\rho(t_{10})) = T^{-1}\). By
767	  \ref{lem:P1_polyToAway_surjective} (for the indices \((1,0)\)) every \(z \in A_{(X_1)}\)
768	  is a polynomial in \(t_{10}\) with coefficients in \(k\); both sides of the claim are
769	  \(k\)-algebra homomorphisms in \(z\), and they agree on \(t_{10}\).
770	\end{proof}
771	
772	\begin{lemma}[Laurent span on the overlap ring]
773	  \label{lem:P1_overlap_span}
774	  \lean{AlgebraicGeometry.P1.exists_awayToOverlap_add}
775	  \uses{def:P1_awayToOverlapLeft, def:P1_awayToOverlapRight}
776	  \leanok
777	  Every \(w \in A_{(X_0 X_1)}\) can be written as \(w = \lambda(z_0) + \rho(z_1)\) with
778	  \(z_0 \in A_{(X_0)}\) and \(z_1 \in A_{(X_1)}\).
779	\end{lemma}
780	\begin{proof}
781	  \leanok
782	  \uses{lem:laurent_span, def:P1_overlapAlgEquiv, lem:P1_overlap_res_left,
783	    lem:P1_overlap_res_right, def:P1_awayAlgEquiv}
784	  Write \(\theta(w) = p(T) + q(T^{-1})\) by \ref{lem:laurent_span} and set
785	  \(z_0 = \alpha_0^{-1}(p)\), \(z_1 = \alpha_1^{-1}(q)\). By
786	  \ref{lem:P1_overlap_res_left} and \ref{lem:P1_overlap_res_right},
787	  \(\theta(\lambda(z_0) + \rho(z_1)) = p(T) + q(T^{-1}) = \theta(w)\), and \(\theta\) is
788	  injective.
