880	  \uses{def:P1}
881	  \leanok
882	  A \emph{Laurent chart pair} on \(\PP^1\) consists of open subsets
883	  \(V_0, V_1, V_{01} \subseteq \PP^1\) with \(V_{01} \subseteq V_0\),
884	  \(V_{01} \subseteq V_1\) and \(V_0 \cap V_1 = V_{01}\), all three affine, covering the
885	  projective line (\(V_0 \cup V_1 = \PP^1\)), together with ring isomorphisms
886	  \[
887	    \Gamma_0 : \Gamma(\PP^1, V_0) \cong k[t], \quad
888	    \Gamma_1 : \Gamma(\PP^1, V_1) \cong k[t], \quad
889	    \Gamma_{01} : \Gamma(\PP^1, V_{01}) \cong k[T, T^{-1}],
890	  \]
891	  such that, under these identifications, restriction \(V_{01} \subseteq V_0\) is
892	  \(t \mapsto T\) and restriction \(V_{01} \subseteq V_1\) is \(t \mapsto T^{-1}\).
893	\end{definition}
894	
895	\begin{theorem}[Laurent span for a chart pair]
896	  \label{thm:laurentChartPair_span}
897	  \lean{AlgebraicGeometry.LaurentChartPair.exists_res_add_res}
898	  \uses{def:LaurentChartPair}
899	  \leanok
900	  Let \((V_0, V_1, V_{01}, \Gamma_0, \Gamma_1, \Gamma_{01})\) be a Laurent chart pair on
901	  \(\PP^1\). Every section \(z \in \Gamma(\PP^1, V_{01})\) is the sum of a restriction from
902	  \(V_0\) and a restriction from \(V_1\): there are \(a \in \Gamma(\PP^1, V_0)\) and
903	  \(b \in \Gamma(\PP^1, V_1)\) with \(z = a|_{V_{01}} + b|_{V_{01}}\).
904	\end{theorem}
905	\begin{proof}
906	  \leanok
907	  \uses{lem:laurent_span}
908	  Write \(\Gamma_{01}(z) = p(T) + q(T^{-1})\) by \ref{lem:laurent_span} and set
909	  \(a = \Gamma_0^{-1}(p)\), \(b = \Gamma_1^{-1}(q)\). By the two restriction conditions,
910	  \(\Gamma_{01}(a|_{V_{01}} + b|_{V_{01}}) = p(T) + q(T^{-1}) = \Gamma_{01}(z)\), and
911	  \(\Gamma_{01}\) is injective.
912	\end{proof}
913	
914	\begin{definition}[The canonical Laurent chart pair]
915	  \label{def:P1_laurentChartPair}
916	  \lean{AlgebraicGeometry.P1.laurentChartPair}

